import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Getting Started","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Download & Installation","slug":"_1-download-installation","link":"#_1-download-installation","children":[{"level":3,"title":"Installer (Lertaro-Setup.exe, Recommended)","slug":"installer-lertaro-setup-exe-recommended","link":"#installer-lertaro-setup-exe-recommended","children":[]},{"level":3,"title":"Portable Edition (Lertaro-Portable.zip)","slug":"portable-edition-lertaro-portable-zip","link":"#portable-edition-lertaro-portable-zip","children":[]}]},{"level":2,"title":"2. Architecture Overview","slug":"_2-architecture-overview","link":"#_2-architecture-overview","children":[]},{"level":2,"title":"3. Three Window Modes","slug":"_3-three-window-modes","link":"#_3-three-window-modes","children":[]},{"level":2,"title":"4. First Search & Basic Navigation","slug":"_4-first-search-basic-navigation","link":"#_4-first-search-basic-navigation","children":[{"level":3,"title":"Type to Search","slug":"type-to-search","link":"#type-to-search","children":[]},{"level":3,"title":"Navigating & Opening Results","slug":"navigating-opening-results","link":"#navigating-opening-results","children":[]},{"level":3,"title":"Action Menu & Context Actions","slug":"action-menu-context-actions","link":"#action-menu-context-actions","children":[]}]}],"relativePath":"user-guide/getting-started.md","filePath":"user-guide/getting-started.md","lastUpdated":1791060275000}`),a={name:`user-guide/getting-started.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h1><p>Welcome to Lertaro! Lertaro is a file search launcher and productivity tool built for Windows. This guide walks you through installation options, core architecture, three distinct window modes, and essential search workflows.</p><h2 id="_1-download-installation" tabindex="-1">1. Download &amp; Installation <a class="header-anchor" href="#_1-download-installation" aria-label="Permalink to “1. Download &amp; Installation”">​</a></h2><p>You can get the latest release from the official homepage. Each release provides installer and portable artifacts for native <strong>x64</strong> and <strong>ARM64</strong> application builds:</p><h3 id="installer-lertaro-setup-exe-recommended" tabindex="-1">Installer (<code>Lertaro-Setup.exe</code>, Recommended) <a class="header-anchor" href="#installer-lertaro-setup-exe-recommended" aria-label="Permalink to “Installer (Lertaro-Setup.exe, Recommended)”">​</a></h3><ul><li><strong>Automated Configuration</strong>: The setup wizard automatically installs the required .NET desktop runtime; on first launch, Lertaro itself registers the background indexing service and configures the startup entry.</li><li><strong>In-Place Upgrades</strong>: Supports background update checks and one-click in-place upgrades.</li></ul><h3 id="portable-edition-lertaro-portable-zip" tabindex="-1">Portable Edition (<code>Lertaro-Portable.zip</code>) <a class="header-anchor" href="#portable-edition-lertaro-portable-zip" aria-label="Permalink to “Portable Edition (Lertaro-Portable.zip)”">​</a></h3><ul><li><strong>Extract and Run</strong>: Unzip to any folder and run immediately without installation.</li><li><strong>Runtime Dependency</strong>: If your system lacks the required .NET desktop runtime, run the bundled <code>install-dotnet-runtime.bat</code> script once.</li><li><strong>Self-Contained Data Storage</strong>: The portable edition saves machine-wide data to <code>Data\\Machine</code> alongside the application, and user settings to <code>Data\\Users\\&lt;SID hash&gt;</code>. If the <code>Data</code> directory does not exist yet, it falls back to <code>%ProgramData%\\Lertaro</code> and <code>%LocalAppData%\\Lertaro</code> for compatibility; once created, it prioritizes local data as a fully self-contained instance.</li><li><strong>Locked When the Service Is Installed</strong>: Installing the background service (you approve one UAC prompt) locks the portable folder. Only administrators can change the application files, <code>Data\\Machine</code> is written by the service alone, and each user&#39;s <code>Data\\Users\\&lt;SID hash&gt;</code> folder is private to that user. Updating or removing a portable copy therefore needs administrator rights; <code>portable-cleanup.bat</code> asks for them itself.</li><li><strong>Clean Removal</strong>: Before deleting the portable folder, run the bundled <code>portable-cleanup.bat</code> script. It stops and uninstalls the background service, and removes current-user <code>lertaro://</code> URI registrations and startup entries.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>If you are using a Windows on ARM device (such as Surface Pro X or Snapdragon laptops), download the native <code>Lertaro-Setup-arm64.exe</code> or <code>Lertaro-Portable-arm64.zip</code> for maximum performance and battery efficiency.</p></div><h2 id="_2-architecture-overview" tabindex="-1">2. Architecture Overview <a class="header-anchor" href="#_2-architecture-overview" aria-label="Permalink to “2. Architecture Overview”">​</a></h2><p>When running Lertaro for the first time, it installs and launches a dedicated Windows service (service name <code>LertaroService</code>, binary <code>Lertaro.Service.exe</code>). Understanding this separation helps you get the most out of the system:</p><ul><li><strong>Foreground App (UI &amp; Interaction)</strong>: Renders search windows, floating panels, action menus, keyboard hooks, and interactive previews. The foreground process keeps a low memory footprint and instant responsiveness.</li><li><strong>Background Service (Indexing &amp; Data)</strong>: Runs with service privileges in the background, continuously monitoring NTFS / ReFS USN change journals, tracking filesystem events, managing network drives, and maintaining an in-memory index tree.</li><li><strong>Architectural Benefits</strong>: Restarting, updating, or closing the UI never loses the background index or triggers full rescans. Heavy indexing tasks never stutter your keystrokes. You can check service status and health at any time under <a href="./settings/service-status.html"><strong>Settings → Service Status</strong></a>.</li></ul><h2 id="_3-three-window-modes" tabindex="-1">3. Three Window Modes <a class="header-anchor" href="#_3-three-window-modes" aria-label="Permalink to “3. Three Window Modes”">​</a></h2><p>Lertaro is not limited to a single search window. It adapts to different workflows with three purpose-built window modes:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Window Mode</th><th style="text-align:left;">Default Trigger</th><th style="text-align:left;">Key Features &amp; Design Focus</th><th style="text-align:left;">Best Used For</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Quick Window</strong></td><td style="text-align:left;">Double-tap <code>Ctrl</code> (Customizable)</td><td style="text-align:left;">Compact centered floating bar with type-to-search, number key jumps, and full keyboard navigation</td><td style="text-align:left;">Frequent app launching, quick calculations, translations, and fast file lookup</td></tr><tr><td style="text-align:left;"><strong>Full Window</strong></td><td style="text-align:left;">Taskbar/Start shortcut, or <code>Ctrl+F</code></td><td style="text-align:left;">Full-featured large window with tabular results, sidebar filter groups, column sorting, and built-in Space Analyzer</td><td style="text-align:left;">Deep file browsing, broad exploration, disk space cleaning, and batch management</td></tr><tr><td style="text-align:left;"><strong>Inline Window</strong></td><td style="text-align:left;">Type a letter or digit inside a file dialog / file manager (or dock it in Explorer)</td><td style="text-align:left;">Embedded directly into standard Windows file dialogs or third-party file managers. The card never steals the keyboard: keep typing in the dialog&#39;s own field, and double-tap <code>Ctrl</code> (your configured summon hotkey) to move the caret into the card</td><td style="text-align:left;">Quick destination locating when opening or saving files in external software</td></tr></tbody></table><p>All three window modes share the exact same underlying search engine, shortcut scheme, filter rules, and action menus.</p><h2 id="_4-first-search-basic-navigation" tabindex="-1">4. First Search &amp; Basic Navigation <a class="header-anchor" href="#_4-first-search-basic-navigation" aria-label="Permalink to “4. First Search &amp; Basic Navigation”">​</a></h2><h3 id="type-to-search" tabindex="-1">Type to Search <a class="header-anchor" href="#type-to-search" aria-label="Permalink to “Type to Search”">​</a></h3><p>Simply open the search window and start typing. Results appear in real time (sub-millisecond latency). Search matching uses fuzzy jump matching by default — characters do not need to be contiguous. For advanced syntax, operators, and modifiers, see <a href="./search-syntax.html"><strong>Search Syntax</strong></a>.</p><h3 id="navigating-opening-results" tabindex="-1">Navigating &amp; Opening Results <a class="header-anchor" href="#navigating-opening-results" aria-label="Permalink to “Navigating &amp; Opening Results”">​</a></h3><ul><li><strong>Move Selection</strong>: Use arrow keys <code>↑</code> / <code>↓</code> (or configured navigation hotkeys <code>Ctrl+P</code> / <code>Ctrl+N</code>) to move selection up and down.</li><li><strong>Open Directly</strong>: Press <code>Enter</code> to open the highlighted file or launch the application.</li><li><strong>Reveal in Explorer</strong>: Press <code>Ctrl+Enter</code> to locate and select the item directly in Windows File Explorer.</li><li><strong>Run as Administrator</strong>: Press <code>Ctrl+Shift+Enter</code> to launch the selected application with administrative privileges.</li><li><strong>Direct Number Jump</strong>: In the Quick Window, press <code>Ctrl</code> + <code>1</code>–<code>9</code> to jump directly to any of the first 9 results.</li></ul><h3 id="action-menu-context-actions" tabindex="-1">Action Menu &amp; Context Actions <a class="header-anchor" href="#action-menu-context-actions" aria-label="Permalink to “Action Menu &amp; Context Actions”">​</a></h3><p>Press <code>Ctrl+O</code> or <code>→</code> on the highlighted item to expand the <strong>Action Menu</strong>, offering path copying, file operations, properties, and plugin extensions. Those two keys belong to the Quick Window (and to the inline card outside file dialogs); in the Full Window use right-click or the <code>Apps</code> key instead. Read <a href="./actions-and-preview.html"><strong>Actions &amp; Preview</strong></a> and <a href="./hotkeys.html"><strong>Hotkeys</strong></a> for more tips.</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};